tool_input.command:
foreach ($d in @("D:\repository\苏住房防汛C端-wt-font-size2","D:\repository\苏州市房地产监测V3-wt-bug6105")) {
  Write-Host "===== $d ====="
  if (Test-Path "$d/.git") {
    $gitfile = Get-Content "$d/.git" -ErrorAction SilentlyContinue
    Write-Host ".git entry: $gitfile"
  } else {
    Write-Host "no .git file/link"
  }
  Write-Host "--- status (short) ---"
  git -C "$d" status --short 2>&1 | Select-Object -First 20
  Write-Host "--- branch / log ---"
  git -C "$d" rev-parse --abbrev-ref HEAD 2>&1
  git -C "$d" log --oneline -3 2>&1
  Write-Host ""
}

$root = "D:\repository\苏住房G"
Write-Host "=== git worktree list (苏住房G) ==="
git -C $root worktree list 2>&1
Write-Host ""
Write-Host "=== .git/worktrees registration dir ==="
$wt = Join-Path $root ".git/worktrees"
if (Test-Path $wt) { Get-ChildItem $wt | Select-Object Name } else { "no .git/worktrees" }
Write-Host ""
Write-Host "=== nested .git files (worktree markers) under $root ==="
Get-ChildItem $root -Recurse -Force -Filter ".git" -ErrorAction SilentlyContinue | ForEach-Object {
  $p = $_.FullName
  if ($_.PSIsContainer) { "DIR  $p" } else { "FILE $p -> " + (Get-Content $p -Raw).Trim() }
}

$sub = "D:\repository\苏住房G\zhi2-web-admin"
$base = "develop/v2.6.2-suzhufang"
Write-Host "=== branches merged into $base (submodule) ==="
git -C $sub branch --merged $base 2>&1
Write-Host ""
foreach ($b in @("develop/v2.6.2-suzhufang-li","develop/v2.6.2-suzhufang-evaluation")) {
  Write-Host "=== merge check: $b -> $base ==="
  git -C $sub merge-base --is-ancestor $b $base 2>&1
  if ($LASTEXITCODE -eq 0) { "RESULT: $b IS merged into $base" } else { "RESULT: $b is NOT merged into $base" }
}
Write-Host ""
Write-Host "=== worktree cleanliness (status --short) ==="
foreach ($w in @("D:\repository\苏住房G\worktrees\bug5897","D:\repository\苏住房G\worktrees\task2192")) {
  Write-Host "--- $w ---"
  git -C $w status --short 2>&1
}
